import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./BuyHouseList.css"; // reuse the same CSS

function formatCurrencyINR(n) {
  if (n == null || isNaN(n)) return "₹0.00";
  const v = Number(n);
  if (v <= 0) return "₹0.00";
  if (v >= 1e7) return `₹${(v / 1e7).toFixed(2)} Cr`;
  if (v >= 1e5) return `₹${(v / 1e5).toFixed(2)} L`;
  return `₹${v.toLocaleString("en-IN")}`;
}

export default function BuyHouseList() {
  const navigate = useNavigate();
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [revealed, setRevealed] = useState({});
  const [predicted, setPredicted] = useState({});
  const [predicting, setPredicting] = useState({});
  const [lightboxSrc, setLightboxSrc] = useState(null);

  const openLightbox = (src) => setLightboxSrc(src);
  const closeLightbox = () => setLightboxSrc(null);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setErr("");
      try {
        const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/buy/houses`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        setItems(Array.isArray(data) ? data : []);
      } catch (e) {
        setErr("Unable to fetch house listings. Please try again.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") closeLightbox(); };
    if (lightboxSrc) window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [lightboxSrc]);

  const num = (x, def = 0) => {
    const v = Number(x);
    return Number.isFinite(v) ? v : def;
  };

  async function doPredict(item) {
    const payload = {
      bedrooms: num(item.bedrooms, 0),
      bathrooms: num(item.bathrooms, 0),
      area_sqft: num(item.area_sqft, 0),
      plot_sqft: num(item.plot_sqft, 0),
      floors: num(item.floors, 1),
      age_years: num(item.age_years, 0),
      city: item.city || "",
      district: item.district || "",
      state: item.state || "",
      latitude: num(item.latitude, 0),
      longitude: num(item.longitude, 0),
      askingPrice: num(item.actualPrice, 0)
    };

    setPredicting((p) => ({ ...p, [item.id]: true }));
    try {
      const base = process.env.REACT_APP_HOUSE_API || process.env.REACT_APP_BACKEND_URL;
      const res = await fetch(`${base}/predict/house`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!res.ok) throw new Error(await res.text() || `HTTP ${res.status}`);
      const data = await res.json();
      setPredicted((p) => ({ ...p, [item.id]: data }));
    } catch (e) {
      console.error("House predict error:", e);
      setPredicted((p) => ({ ...p, [item.id]: null }));
      alert(`Prediction failed: ${e?.message || e}`);
    } finally {
      setPredicting((p) => ({ ...p, [item.id]: false }));
    }
  }

  const goDetails = (item) => navigate(`/house/${item.id}`);

  if (loading) return <div className="buy-loading">Loading house listings...</div>;
  if (err) return <div className="buy-error">{err}</div>;
  if (!items.length) return <div className="buy-empty">No house listings found.</div>;

  return (
    <div className="buy-root">
      {items.map((h) => {
        const isRevealed = revealed[h.id];
        const predObj = predicted[h.id];
        const pred = predObj?.price;
        const actual = h.actualPrice != null ? Number(h.actualPrice) : 0;
        const showDeal = typeof pred === "number" && actual > 0 && pred < actual;
        const areaSqft = num(h.area_sqft, 0);

        return (
          <div className="buy-card" key={h.id}>
            {/* Left: image */}
            <div className="buy-card-left">
              <div className="buy-thumb">
                {h.image ? (
                  <button
                    type="button"
                    className="thumb-click"
                    onClick={() => openLightbox(`${process.env.REACT_APP_BACKEND_URL}${h.image}`)}
                    aria-label="View full image"
                  >
                    <img src={`${process.env.REACT_APP_BACKEND_URL}${h.image}`} alt="" />
                  </button>
                ) : (
                  <div className="no-img">No Image</div>
                )}
                <span className="badge">House</span>
              </div>
            </div>

            {/* Middle: meta */}
            <div className="buy-card-mid">
              <div className="buy-title">
                {h.bedrooms ? `${h.bedrooms} BHK` : "House"} in {h.city || h.district || h.state || h.location || ""}
              </div>

              <div className="buy-meta">
                <div className="price">{formatCurrencyINR(actual)}</div>
                {areaSqft > 0 && <div className="meta-item">{areaSqft.toLocaleString()} sq.ft</div>}
                {h.propertyType && <div className="meta-item">{h.propertyType}</div>}
              </div>

              {typeof pred === "number" && (
                <div className={`predict-row ${showDeal ? "deal-ok" : "deal-warn"}`}>
                  <span>Model price: {formatCurrencyINR(pred)}</span>
                  {showDeal ? (
                    <span className="deal good">Good deal</span>
                  ) : (
                    <span className="deal warn">Above model</span>
                  )}
                  <div className="sub">
                    <span>
                      ₹/sqft: {predObj?.price_per_sqft != null
                        ? `₹${Number(predObj.price_per_sqft).toLocaleString("en-IN")}`
                        : "N/A"}
                    </span>
                  </div>
                </div>
              )}

              {(h.location || h.city || h.district || h.state) && (
                <div className="location-row">
                  <span className="pin">📍</span>
                  <span className="loc-text">
                    {h.location || [h.city, h.district, h.state].filter(Boolean).join(", ")}
                  </span>
                </div>
              )}
            </div>

            {/* Right: actions */}
            <div className="buy-card-right">
              <div className="btn-row">
                <button
                  className="btn btn-primary"
                  onClick={() => setRevealed((r) => ({ ...r, [h.id]: !isRevealed }))}
                >
                  {isRevealed ? h.contact || "NA" : "Contact"}
                </button>

                <button className="btn details" onClick={() => goDetails(h)}>
                  Go Details
                </button>

                <button
                  className="btn btn-success"
                  disabled={predicting[h.id]}
                  onClick={() => doPredict(h)}
                >
                  {predicting[h.id] ? "Predicting..." : "Predict"}
                </button>
              </div>
            </div>
          </div>
        );
      })}

      {lightboxSrc && (
        <div className="lb-overlay" onClick={closeLightbox} role="dialog" aria-modal="true">
          <div className="lb-content" onClick={(e) => e.stopPropagation()}>
            <button className="lb-close" onClick={closeLightbox} aria-label="Close">×</button>
            <img src={lightboxSrc} alt="" />
          </div>
        </div>
      )}
    </div>
  );
}
